    transfer: [
      B.text('075_t_situation', 'Pärast kontrolli', 'Kontroll 15 on tehtud. Loe näidistagasisidet, koosta plaan ja harjuta kriitilise lugemise oskust ka igapäevases elus — iga uudis on võimalus harjutada.'),
      B.reading('075_t_read', 'Loe näidistagasisidet.', 'Loe ja vasta küsimustele.', 'Tagasiside: Andrei, kontroll 15',
        'Hea Andrei! Sinu kontrolli tulemus on kokku seitsekümmend kaks protsenti, seega oled mooduli läbinud. Kõige paremini läks sul argumentide analüüs. Sa nägid kohe, et loomaaia direktori väide, mille järgi elav loom loob tugevama side kui ekraan, on hinnang ja et sellel puudub tõend. Samuti selgitasid hästi, miks Euroopa naaritsa näide on tugev: see on konkreetne, kontrollitav ja seotud väitega. See näitab, et oled õppinud küsima, millele väide toetub. Suulises reaktsioonis olid sa enesekindel ja tõid hea näite oma lapsepõlvest. Kui küsisin, mis on autori enda seisukoht, vastasid sa alguses, et autor on loomaaedade vastu. See ei olnud täpne, sest autor esitab mõlemad pooled ja lõpus toetab pigem ekspertide kompromissi. Pärast täpsustavat küsimust märkasid sa seda ise, mis oli hea. Proovi järgmisel korral enne vastamist mõelda, millele autor annab rohkem ruumi ja kuidas tekst lõpeb. Kõige rohkem punkte kaotasid sa lugemise järeldusküsimustes. Kolmele küsimusele vastasid sa lausega, mis oli tekstist peaaegu sõna-sõnalt kopeeritud. Näiteks küsimusele, miks on populaarsed loomad vastuoluline küsimus, kirjutasid ainult „seal peamiselt külastajate meelitamiseks”. See näitab, et leidsid õige koha, kuid ei näita, et said aru. Hea vastus oleks selgitanud, et need loomad ei ole ohustatud, kuid nad toovad külastajaid, kelle raha toetab looduskaitset. Kokkuvõte oli üldiselt täpne, kuid ühes lauses oli sinu hinnang: „Kahjuks kannatavad loomad puurides.” Sõna „kahjuks” kuulub reaktsiooni, mitte kokkuvõttesse. Reaktsioonis eraldasid sa oma arvamuse selgelt ja põhjendasid seda hästi. Järgmise mooduli jaoks soovitan kolme asja. Esiteks vasta järeldusküsimustele alati oma sõnadega, kasutades sõnu „sest”, „seetõttu” või „see tähendab, et”. Teiseks loe iga päev üks uudis ja leia sealt üks fakt, üks hinnang ja üks oletus. Kolmandaks harjuta autori seisukoha määramist nii, et vaatad, kuidas tekst lõpeb. Oled teinud suurt edu ja oled valmis viimasteks B2 mooduliteks. Kui sul on küsimusi, võime need järgmise tunni alguses läbi arutada. Pea meeles, et kriitiline lugemine on oskus, mis tuleb kasuks mitte ainult eksamil, vaid ka igapäevaelus.',
        [['Mis on Andrei tulemus?', '72 protsenti'], ['Mis läks kõige paremini?', 'argumentide analüüs'], ['Mis oli autori seisukoha viga?', 'ütles, et autor on loomaaedade vastu, kuigi autor toetab kompromissi'], ['Mida soovitab õpetaja seisukoha määramiseks?', 'vaadata, millele autor annab ruumi ja kuidas tekst lõpeb'], ['Miks ei andnud kopeeritud vastus täispunkte?', 'see näitab, et leidis koha, kuid mitte, et sai aru'], ['Mis oli kokkuvõtte viga?', 'hinnang „kahjuks”'], ['Millised on kolm soovitust?', 'järeldusvastused oma sõnadega, fakt/hinnang/oletus uudisest, teksti lõpp']]),
      B.table('075_t_plan', 'Minu plaan.', 'Täida tabel oma tulemuse põhjal.', 'osa, tulemus, mis läks hästi, mida harjutan', ['lugemine: faktiküsimused | | |', 'lugemine: järeldusküsimused | | |', 'argumentide analüüs | | |', 'kokkuvõte | | |', 'suuline reaktsioon | | |']),
      B.transformation('075_t_trans', 'Kopeeritud → oma sõnadega.', 'Kirjuta kopeeritud vastus ümber oma sõnadega täislausena.', [['„seal peamiselt külastajate meelitamiseks”', 'sest / see tähendab', 'Need loomad ei ole ohustatud, kuid toovad külastajaid, kelle raha toetab looduskaitset.'], ['„korduvad käitumismustrid”', 'see tähendab, et', 'See tähendab, et loom on stressis ja kordab sama liigutust.'], ['„looduskaitseasutus”', 'oma sõnadega', 'Loomaaia eesmärk on nüüd päästa ohustatud liike.'], ['„loobuda liikidest, mis kannatavad”', 'seetõttu', 'Eksperdid soovitavad elevante ja jääkarusid mitte pidada, sest nad kannatavad.'], ['„teadlased on jagatud”', 'oma sõnadega', 'Teadlased ei ole ühel meelel: osa toetab, osa kritiseerib.'], ['„nõuavad aega”', 'sest', 'Muutused ei toimu kiiresti, sest uued alad on kallid.']]),
      B.speaking('075_t_say', 'Iga päeva uudis.', 'Vali üks tänane uudis (või õpetaja antud uudis) ja analüüsi seda 3 minutiga: peamine mõte, üks fakt, üks hinnang, üks oletus, kõige tugevam argument ja sinu reaktsioon.', ['Mis on peamine mõte?', 'Leia fakt, hinnang ja oletus.', 'Mis on kõige tugevam argument?', 'Mis on sinu reaktsioon?'], [180, 210], ['uudise järgi', 'see on hinnang, sest', 'see on oletus', 'minu arvates']),
      B.rolecards('075_t_peer', 'Paariline küsib.', 'Rääkige 3 minutit. Üks esitab järeldusküsimusi, teine vastab ainult oma sõnadega.',
        'Esita paarilisele 3 järeldusküsimust loomaaia tekstist („Miks…?”, „Mida autor mõtleb…?”). Kui vastus on kopeeritud, palu öelda oma sõnadega.', 'Vasta igale küsimusele oma sõnadega täislausega, kasutades „sest”, „see tähendab”, „seetõttu”.',
        ['Miks…?', 'Mida autor sellega mõtleb?', 'Ütle palun oma sõnadega.'], ['See tähendab, et…', 'Sest…', 'Teisiti öeldes…']),
      B.errorfix('075_t_fix', 'Andrei vead.', 'Paranda Andrei tüüpilised vead.', [['Autor on loomaaedade vastu.', 'Autor esitab mõlemad pooled ja toetab ekspertide kompromissi.'], ['Kahjuks kannatavad loomad puurides.', 'Uuringute järgi on paljud suured loomad vangistuses stressis.'], ['Seal peamiselt külastajate meelitamiseks.', 'Populaarseid loomi peetakse külastajate pärast, kelle raha toetab looduskaitset.'], ['Direktor tõestas oma väite.', 'Direktori väide on hinnang, sest sellel puudub tõend.'], ['Kõik teavad, et loomaaiad on head.', 'Loomaaia direktori sõnul päästavad loomaaiad ohustatud liike.'], ['Minu arvates autor väidab, et…', 'Autor väidab, et… Minu arvates…']]),
      B.writing('075_t_write', 'Kiri iseendale.', 'Kirjuta 10–12 lauset: mida oled moodulis 15 kriitilisest lugemisest õppinud, mis on veel raske ja kuidas harjutad igapäevaselt.', [10, 12], ['olen õppinud', 'fakt', 'hinnang', 'oma sõnadega', 'harjutan'], 4),
      B.selfcheck('075_t_self', ['Ma mõistan tagasisidet.', 'Ma koostasin plaani.', 'Ma vastasin oma sõnadega.', 'Ma analüüsisin päris uudist.'], 'Moodul 15 läbitud'),
    ],
